ROOT = "/bench/repo"

# Patterns that reference store.Memo struct (qualified)
qualified = re.compile(r'store\.Memo([^A-Za-z_]|$)')

# Patterns for same-package unqualified Memo struct references
# Exclude MemoRelation, MemoShare, FindMemo, UpdateMemo, DeleteMemo, MemoPayload, MemoFilter
unqualified_bad_suffix = re.compile(
    r'Memo(?:Relation|Share|Filter|Payload|Name|Service|Comment|RelationComment|RelationReference|ShareService|Attachment|Batch|Update|Delete|Find|Create|List|Get|Upsert|Builder|FilterTest|FilterTestContext|Builder)'
)
unqualified_patterns = [
    re.compile(r'\*Memo([^A-Za-z_]|$)'),
    re.compile(r'&Memo\{'),
    re.compile(r'\[\]\*Memo([^A-Za-z_]|$)'),
    re.compile(r'\[\]Memo([^A-Za-z_]|$)'),
    re.compile(r'\bMemo\{'),
    re.compile(r'\bvar\s+memo\s+Memo\b'),
    re.compile(r'\bmemo\s+Memo\b'),
    re.compile(r'func\s+[^(]*\([^)]*\*Memo([^A-Za-z_]|$)'),
    re.compile(r'\(\*Memo\)'),
    re.compile(r'\bcreate\s+\*Memo\b'),
    re.compile(r'\bupdate\s+\*UpdateMemo\b'),  # UpdateMemo is different type
]

def has_unqualified_memo(line):
    for pat in unqualified_patterns:
        m = pat.search(line)
        if m:
            # check it's not a false positive suffix
            idx = line.find('Memo')
            while idx != -1:
                rest = line[idx:]
                if not unqualified_bad_suffix.match(rest[len('Memo')-len(rest):] if False else rest[4:]):
                    # simpler: check char after Memo
                    after = idx + 4
                    if after < len(line):
                        suffix = line[after:]
