import re
import os

ROOT = "/bench/repo"

# Patterns that reference store.Memo struct (qualified)
qualified = re.compile(r'store\.Memo([^A-Za-z_]|$)')

# Patterns for same-package unqualified Memo struct references
# Exclude MemoRelation, MemoShare, FindMemo, UpdateMemo, DeleteMemo, MemoPayload, MemoFilter
unqualified_bad_suffix = re.compile(
    r'Memo(?:Relation|Share|Filter|Payload|Name|Service|Comment|RelationComment|RelationReference|ShareService|Attachment|Batch|Update|Delete|Find|Create|List|Get|Upsert|Builder|FilterTest|FilterTestContext|Builder)'
)
unqualified_patterns = [
    re.compile(r'\*Memo([^A-Za-z_]|$)'),
    re.compile(r'&Memo\{'),
    re.compile(r'\[\]\*Memo([^A-Za-z_]|$)'),
    re.compile(r'\[\]Memo([^A-Za-z_]|$)'),
    re.compile(r'\bMemo\{'),
    re.compile(r'\bvar\s+memo\s+Memo\b'),
    re.compile(r'\bmemo\s+Memo\b'),
    re.compile(r'func\s+[^(]*\([^)]*\*Memo([^A-Za-z_]|$)'),
    re.compile(r'\(\*Memo\)'),
    re.compile(r'\bcreate\s+\*Memo\b'),
    re.compile(r'\bupdate\s+\*UpdateMemo\b'),  # UpdateMemo is different type
]

def has_unqualified_memo(line):
    for pat in unqualified_patterns:
        m = pat.search(line)
        if m:
            # check it's not a false positive suffix
            idx = line.find('Memo')
            while idx != -1:
                rest = line[idx:]
                if not unqualified_bad_suffix.match(rest[len('Memo')-len(rest):] if False else rest[4:]):
                    # simpler: check char after Memo
                    after = idx + 4
                    if after < len(line):
                        suffix = line[after:]
                        if unqualified_bad_suffix.match('Memo' + suffix.split()[0] if suffix else ''):
                            pass
                        elif suffix and suffix[0].isalpha() or (len(suffix)>1 and suffix[0]=='_' and suffix[1].isalpha()):
                            # has longer identifier
                            word = re.match(r'([A-Za-z_][A-Za-z0-9_]*)', suffix)
                            if word and word.group(1) in ('Relation','Share','Filter','Payload','Name','Service','Comment',
                                'RelationComment','RelationReference','Update','Delete','Find','Create','List','Get',
                                'Upsert','Builder','Attachment','Batch','FilterTest','FilterTestContext','FilterFunctions'):
                                idx = line.find('Memo', idx+1)
                                continue
                    return True
            # pattern matched
            if pat.pattern.startswith(r'\*Memo') or pat.pattern.startswith(r'&Memo') or pat.pattern.startswith(r'\[\]\*Memo'):
                # verify suffix
                for m2 in re.finditer(r'(?<![A-Za-z_])Memo([^A-Za-z_]|$)', line):
                    return True
                for m2 in re.finditer(r'&Memo\{', line):
                    return True
                for m2 in re.finditer(r'\[\]\*Memo([^A-Za-z_]|$)', line):
                    return True
    return False

def analyze_file(path):
    try:
        with open(path, 'r', errors='replace') as f:
            content = f.read()
            lines = content.splitlines()
    except:
        return None

    rel = path.replace(ROOT+'/', '')
    pkg_match = re.search(r'^package\s+(\S+)', content, re.M)
    pkg = pkg_match.group(1) if pkg_match else ''
    is_store_pkg = '/store/' in path and '/proto/' not in path and pkg == 'store'
    is_store_sub = '/store/db/' in path or '/store/cache/' in path

    evidence = []
    for i, line in enumerate(lines, 1):
        if 'MemoPayload' in line and 'store.Memo' not in line and not re.search(r'(?<![A-Za-z_])Memo([^A-Za-z_]|$)', line.replace('MemoPayload','')):
            pass
        if qualified.search(line):
            if 'MemoPayload' not in line.split('store.Memo')[1][:20] if 'store.Memo' in line else True:
                # exclude store.MemoPayload, store.MemoRelation, store.MemoShare
                if re.search(r'store\.Memo(?:Payload|Relation|Share)([^A-Za-z_]|$)', line):
                    continue
                evidence.append((i, line.strip()[:120]))
        elif (is_store_pkg or is_store_sub) and re.search(r'(?<![A-Za-z_])Memo(?:Relation|Share|Filter|Payload|NamePrefix|Service|Comment|RelationComment|RelationReference|Update|Delete|Find|Create|List|Get|Upsert|Builder|Attachment|Batch|FilterTest|FilterTestContext|FilterFunctions|ShareService)', line):
            continue
        elif (is_store_pkg or is_store_sub):
            for pat in [r'(?<![A-Za-z_])\*Memo([^A-Za-z_]|$)', r'&Memo\{', r'\[\]\*Memo([^A-Za-z_]|$)', r'(?<![A-Za-z_])var memo Memo\b', r'(?<![A-Za-z_])memo Memo\b', r'func [^(]*\([^)]*\*Memo([^A-Za-z_]|$)', r'create \*Memo\b', r'find \*FindMemo\b']:
                pass
            if re.search(r'(?<![A-Za-z_])\*Memo([^A-Za-z_]|$)', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'&Memo\{', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'\[\]\*Memo([^A-Za-z_]|$)', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'(?<![A-Za-z_])var memo Memo\b', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'(?<![A-Za-z_])memo Memo\b', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'create \*Memo\b', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'\(\*Memo, \*Memo\)', line) or re.search(r'\*Memo, error\)', line):
                evidence.append((i, line.strip()[:120]))
            elif re.search(r'func \(.*\) \w+\([^)]*\*Memo\b', line) and 'FindMemo' not in line and 'UpdateMemo' not in line and 'DeleteMemo' not in line:
                evidence.append((i, line.strip()[:120]))

    if evidence:
        return rel, evidence[:3], len(evidence)
    return None

results = {}
for dirpath, dirnames, filenames in os.walk(ROOT):
    if '/.git' in dirpath or '/node_modules' in dirpath:
        continue
    for fn in filenames:
        if fn.endswith('.go'):
            path = os.path.join(dirpath, fn)
            r = analyze_file(path)
            if r:
                results[r[0]] = (r[1], r[2])

for p in sorted(results.keys()):
    ev, count = results[p]
    print(f"{p}\t({count} refs)\t{ev[0][0]}:{ev[0][1]}")
